import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const CODE_LENGTH = 6;

const StaffCode = () => {
  const navigate = useNavigate();
  const [code, setCode] = useState('');

  const isCodeComplete = code.length === CODE_LENGTH;

  const handleLogin = (e) => {
    e.preventDefault();
    if (!isCodeComplete) return;
    // TODO: запрос к backend для проверки TOTP-кода
    // TODO: navigate('/staff/qr') — рабочий экран с QR (сверстаем после макета)
  };

  return (
    <div className="min-h-screen w-full bg-secondary flex flex-col px-5">
      <div className="mx-auto flex w-full max-w-[440px] flex-1 flex-col">

        {/* Декоративный градиентный блик */}
        <div
          aria-hidden
          className="pointer-events-none mx-auto mt-[88px] h-[170px] w-[260px] rotate-[-20deg] laptop:mt-24 laptop:h-[400px] laptop:w-[600px]"
          style={{
            background:
              'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
          }}
        />

        {/* Заголовок */}
        <h1 className="mt-12 text-center text-4xl leading-[105%] font-semibold text-black laptop:text-[64px] desktop:text-[32px]">
          Введите код
        </h1>

        {/* Подзаголовок */}
        <p className="mt-2 text-center text-sm leading-[120%] text-gray laptop:text-xl laptop:font-normal desktop:text-sm desktop:font-medium">
          На ваш Google Authenticator был выслан код для входа в аккаунт
        </p>

        <form onSubmit={handleLogin} noValidate>
          {/* Код из Google Authenticator: одно поле с разрядкой цифр */}
          <input
            type="text"
            inputMode="numeric"
            autoComplete="one-time-code"
            maxLength={CODE_LENGTH}
            placeholder="000000"
            value={code}
            onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
            aria-label="Код из Google Authenticator"
            className="mt-10 w-full bg-transparent text-center text-3xl tracking-[0.35em] text-black
                       placeholder-gray/40 focus:outline-none laptop:mt-12 laptop:text-4xl desktop:text-[32px]"
          />

          {/* Кнопка входа */}
          <button
            type="submit"
            disabled={!isCodeComplete}
            className={`mt-10 h-12 w-full rounded-full text-sm transition-colors laptop:mt-12 laptop:h-16 laptop:text-xl desktop:text-sm
              ${isCodeComplete
                ? 'bg-accent text-black'
                : 'cursor-not-allowed bg-gray/50 text-primary'}`}
          >
            Войти
          </button>
        </form>
      </div>
    </div>
  );
};

export default StaffCode;
